-- The fuller official Summit Hills report contains survey and tracing numbers
-- absent from the original four-record pilot.
UPDATE intelligence.land_events SET
  effective_on='2024-10-30',
  survey_reference='CR/C/1187; tracing CRC.2881 and CRC/2878',
  original_area_text='23 hectares released; ceding notice identifies 12.110 ha and 9.074 ha parcels',
  summary='Following consent judgment HC/314/2021, the state handed the Nkonib community an approved layout plan. The official report names survey plan CR/C/1187 and tracing numbers CRC.2881 and CRC/2878, while also reporting 12.110 ha and 9.074 ha ceded parcels.',
  updated_at=now()
