WITH events(external_key,event_type,headline,summary,effective_on,admin_level_2,locality,layout_name,plot_reference,survey_reference,court_reference,area_sqm,original_area_text,evidence_tier,confidence) AS (
 VALUES
 ('crs-wilmar-biase-8500ha-allocation','allocation','Over 8,500 hectares and plantation assets transferred to Wilmar subsidiary','The state reports an asset-sale agreement transferring over 8,500 hectares formerly managed by Enghuat Industries/Cross River Estates to Biase Plantations Limited. The article identifies Ibiae and Kalaro estates but supplies no parcel plan.','2025-06-16',NULL,'Biase and Akamkpa','Ibiae and Kalaro oil palm estates',NULL,NULL,NULL,85000000::numeric,'over 8,500 hectares',2::smallint,0.96::numeric),
 ('crs-adiabo-womens-housing-31ha','allocation','31 hectares at Adiabo handed over for women''s housing scheme','The state reports handing 31 hectares at Adiabo to Family Homes Funds for a 70-unit federal women''s housing scheme. No survey reference or boundary was published.','2025-01-15',NULL,'Adiabo',NULL,NULL,NULL,NULL,310000::numeric,'31 hectares',2::smallint,0.97::numeric),
 ('crs-boki-palm-estate-presco-handover','allocation','Boki palm estate handed over to Presco for rehabilitation','The state reports the formal handover of the Boki estate to Presco following a privatization process. The publication does not state its area or boundary.','2026-03-20','Boki','Borum','Boki Palm Estate',NULL,NULL,NULL,NULL,NULL,2::smallint,0.91::numeric),
 ('crs-nsadop-palm-estate-presco-handover','allocation','Nsadop palm estate handed over to Presco for rehabilitation','The state reports the formal handover of the Nsadop estate to Presco following a privatization process. The publication does not state its area or boundary.','2026-03-21','Boki','Nsadop','Nsadop Palm Estate',NULL,NULL,NULL,NULL,NULL,2::smallint,0.91::numeric),
 ('crs-bansara-spin-630ha-site','planning_change','Approximately 630 hectares at Bansara assessed for irrigation development','An official project report describes a technical verification visit across approximately 630 hectares proposed for flood-control and irrigation works under SPIN. This is a project-site report, not evidence of title transfer.','2026-02-23','Ogoja','Bansara','Bansara SPIN site',NULL,NULL,NULL,6300000::numeric,'approximately 630 hectares',2::smallint,0.94::numeric),
 ('crs-obudu-airport-1500ha-acquisition','acquisition','Reported 1,500-hectare acquisition for Obudu international airport','A contemporaneous report quotes the state as having acquired about 1,500 hectares and paid nearly NGN900 million compensation to five land-owning communities for the airport project. The acquisition instrument and survey plan were not found.','2020-12-01','Obudu','Obudu',NULL,NULL,NULL,NULL,15000000::numeric,'about 1,500 hectares',3::smallint,0.86::numeric),
 ('crs-superhighway-occupancy-revocation-2016','revocation','Rights of occupancy revoked along proposed 260 km superhighway corridor','Reports reproduce a 22 January 2016 Weekend Chronicle notice revoking occupancy along the proposed Esighi-to-Bekwarra superhighway. The reported notice described a 200 m offset on each side plus a further 10 km span, excluding reserves and public institutions; 5,200 km2 is a civil-society computation, not surveyed parcel area.','2016-01-22',NULL,'Esighi to Bekwarra','Cross River Superhighway corridor',NULL,NULL,NULL,5200000000::numeric,'reported/contested computation of 5,200 km2',3::smallint,0.84::numeric),
 ('crs-ekorinim-harbour-village-revocation-dispute','court_decision','11.048-hectare Harbour Village revocation and revalidation disputed in court','The reported Court of Appeal matter concerns Harbour Village at Ekorinim, originally vested in the Nigerian Ports Authority and later subject to a 26 November 2007 revocation/revalidation. The source identifies survey plan CR6 859. The judgment text must be reviewed before encoding the final legal effect. ',NULL,'Calabar Municipal','Ekorinim','Harbour Village',NULL,'CR6 859','NPA v Attorney-General of Cross River State & Ors (2014)',110480::numeric,'approximately 11.048 hectares',3::smallint,0.90::numeric),
 ('crs-northern-industrial-estate-7ha-case','court_decision','7.139-hectare federal property dispute at Northern Industrial Estate','The reported appeal concerns federal-agency land along Murtala Mohammed Highway, Block N, Northern Industrial Estate, Ikot Ansa, and challenges state revocation and sale. The final legal effect requires judgment-level review. ',NULL,'Calabar Municipal','Ikot Ansa','Northern Industrial Estate','Block N',NULL,'Government of Cross River State v NTA & Ors (2013)',71390::numeric,'7.139 hectares',3::smallint,0.88::numeric),
 ('crs-ikot-uduak-nitel-10ha-case','court_decision','10.443-hectare Ikot Uduak acquisition and NITEL quarters dispute','The reported appeal traces a 1973 state acquisition of 10.443 hectares for P&T/NITEL, of which 2.639 hectares was developed and 7.804 hectares remained undeveloped. It records a later dispute involving retired NITEL staff.','1973-01-01','Calabar Municipal','Ikot Uduak','NITEL Senior Staff Quarters',NULL,NULL,'Surveyor General of Cross River State & Ors v Opute Jonathan & Ors (2014)',104430::numeric,'10.443 hectares total; 2.639 developed; 7.804 undeveloped',3::smallint,0.89::numeric),
 ('crs-fggc-calabar-additional-11ha-case','court_decision','11.884-hectare additional FGGC Calabar land became subject of return/compensation dispute','The reported appeal says the state surveyed 11.884 hectares of Adohose family land in 1982 for additional FGGC land, advised in 2006 that it was no longer needed, and later disputed whether compensation had been paid. The record is a dispute, not proof of current ownership.','1982-01-01','Calabar Municipal','Calabar','Federal Government Girls College additional land',NULL,NULL,'Hon Minister of Education & Ors v Ekpo & Ors (2016)',118840::numeric,'11.884 hectares additional land',3::smallint,0.88::numeric),
 ('crs-ugep-idomi-ketabebe-dispute-2026','dispute','Ugep challenges proposed Ketabebe land-sharing formula','The Guardian reports a High Court action challenging a proposed 45-40-15 allocation among Ugep, Idomi and the state at the Ketabebe frontier. This records the existence of a live dispute; it does not validate either side''s title claim.','2026-07-04','Yakurr','Ketabebe frontier',NULL,NULL,NULL,NULL,NULL,'reported 45-40-15 sharing ratio',3::smallint,0.90::numeric),
 ('crs-undue-process-allocations-revoked-2025','revocation','State reportedly revoked land allocations made without due process','A report reproducing a governor''s press release says allocations determined to have been made without due process were revoked statewide. No affected-plot schedule was found, so the record cannot identify individual titles.','2025-11-10',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'all allocations described as lacking due process',3::smallint,0.87::numeric),
 ('crs-50000ha-agric-land-programme','acquisition','Budget pipeline covers acquisition, compensation and survey of 50,000 hectares','The 2024 performance report and 2026 proposed budget contain separate lines for acquisition/land rent, crop enumeration and compensation, survey, and ESIA for a 50,000-hectare public-private agriculture programme. It is state-wide programme evidence, not a parcel boundary.','2024-01-01',NULL,NULL,NULL,NULL,NULL,NULL,500000000::numeric,'50,000 hectares, state wide',2::smallint,0.98::numeric),
 ('crs-2024-acquired-land-survey-programme','survey_approval','2024 report records acquired-land survey and boundary-survey programmes','The Q4 budget performance report records Ministry of Lands projects for acquisition and compensation, survey/percolation of government-acquired land, survey/documentation of state facilities and a boundary survey programme. It does not list affected parcels.','2024-12-31',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,2::smallint,0.98::numeric)
)
INSERT INTO intelligence.land_events(external_key,event_type,headline,summary,effective_on,country_code,admin_level_1,admin_level_2,locality,layout_name,plot_reference,survey_reference,court_reference,area_sqm,original_area_text,geometry_status,extraction_confidence,evidence_tier,review_status,search_status,check_status)
SELECT external_key,event_type,headline,summary,effective_on::date,'NG','Cross River',admin_level_2,locality,layout_name,plot_reference,survey_reference,court_reference,area_sqm,original_area_text,'unavailable',confidence,evidence_tier,'accepted','searchable','excluded'
FROM events ON CONFLICT(external_key) DO NOTHING;

