INSERT INTO intelligence.review_events(land_event_id,event_type,actor,reason,snapshot)
SELECT e.id,'accepted','system:cross-river-discovery-pass','Reviewed source-level claim; retained geometry exclusion pending parcel evidence',
 jsonb_build_object('reviewStatus',e.review_status,'searchStatus',e.search_status,'checkStatus',e.check_status,'evidenceTier',e.evidence_tier,'geometryStatus',e.geometry_status)
FROM intelligence.land_events e
WHERE (e.external_key IN (
 'crs-wilmar-biase-8500ha-allocation','crs-adiabo-womens-housing-31ha','crs-boki-palm-estate-presco-handover','crs-nsadop-palm-estate-presco-handover','crs-bansara-spin-630ha-site','crs-obudu-airport-1500ha-acquisition','crs-superhighway-occupancy-revocation-2016','crs-ekorinim-harbour-village-revocation-dispute','crs-northern-industrial-estate-7ha-case','crs-ikot-uduak-nitel-10ha-case','crs-fggc-calabar-additional-11ha-case','crs-ugep-idomi-ketabebe-dispute-2026','crs-undue-process-allocations-revoked-2025','crs-50000ha-agric-land-programme','crs-2024-acquired-land-survey-programme'))
AND NOT EXISTS(SELECT 1 FROM intelligence.review_events r WHERE r.land_event_id=e.id);

-- Down Migration
-- Evidence records are append-only by design. This production-like discovery
-- migration intentionally has no destructive rollback.
